SELECT
    [P1].[SegmentName] AS [c0],
    (SELECT DATEADD(DAY, DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) - ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) % 30, CONVERT(date, '00080827')) FROM (VALUES ((SELECT DATEADD(DAY, 365 * (((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) / 13) - 1) + ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) / 13) / 4 + 30 * ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) % 13) + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) % 13) / 12 * (25 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) / 13) % 4 / 3))) - (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922), [N1].[v]) FROM (VALUES (MAX([T].[PostingDate]))) AS [N1] ([v])))) AS [N1] ([v])) AS [c1],
    COUNT_BIG(*) AS [c2]
FROM [gl].[Documents] AS [T]
INNER JOIN [gl].[Segments] AS [P1] ON [P1].[SegmentId] = [T].[SegmentId]
GROUP BY [P1].[SegmentName]
HAVING ((SELECT DATEADD(DAY, 365 * (((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) / 13) - 1) + ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) / 13) / 4 + 30 * ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) % 13) + LEAST(((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) % 30, (29 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) % 13) / 12 * (25 - ((((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) * 13 + ((DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) - (365 * (((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) - 1) + ((4 * (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922) + 1463) / 1461) / 4)) / 30 + CAST(@qx0_p0 AS int)) / 13) % 4 / 3))) - (DATEDIFF(DAY, CONVERT(date, '00080827'), [N1].[v]) + 2922), [N1].[v]) FROM (VALUES (MAX([T].[PostingDate]))) AS [N1] ([v])) > MIN([T].[PostingDate]))
;

-- parameters
--   @qx0_p0 : QxNumeric QxDecimal(1, 0) Literal = 1
-- columns
--   0 : QxString NotNull key path=Centre.Name Centre.Name
--   1 : QxDate NotNull startOfMonth(addMonths(max(PostingDate), 1, 'et'), 'et')
--   2 : QxNumeric NotNull count()
